    state.hold_pps_components.h_labor_portion = Decimal::from(i64::from((state.pps_data_all.pps_other_data.pps_std_fed_rate * state.pps_data_all.pps_other_data.pps_nat_labor_pct) * state.pps_data_all.pps_data.pps_wage_index));
    state.hold_pps_components.h_nonlabor_portion = Decimal::from(i64::from((state.pps_data_all.pps_other_data.pps_std_fed_rate * state.pps_data_all.pps_other_data.pps_nat_nonlabor_pct) * state.pps_data_all.pps_data.pps_cola));
